DROP TABLE IF EXISTS `activity_logs`;
CREATE TABLE `activity_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `menu` varchar(250) DEFAULT NULL,
  `action` varchar(50) NOT NULL,
  `model` varchar(100) NOT NULL,
  `model_id` bigint(20) unsigned DEFAULT NULL,
  `changes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3581 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



DROP TABLE IF EXISTS `adjust_salary`;
CREATE TABLE `adjust_salary` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `driver_id` int(11) DEFAULT NULL,
  `driver_name` varchar(200) DEFAULT NULL,
  `location` varchar(200) DEFAULT NULL,
  `amount` int(11) NOT NULL,
  `remark` varchar(250) DEFAULT NULL,
  `year` int(11) DEFAULT NULL,
  `month` varchar(200) DEFAULT NULL,
  `from_date` date DEFAULT NULL,
  `created_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `driver_id` (`driver_id`),
  CONSTRAINT `adjust_salary_ibfk_1` FOREIGN KEY (`driver_id`) REFERENCES `staff` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=407 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



DROP TABLE IF EXISTS `bank`;
CREATE TABLE `bank` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bank_name` varchar(100) NOT NULL,
  `ifsc_code` varchar(20) NOT NULL,
  `ac_no` varchar(20) NOT NULL,
  `short_name` varchar(50) NOT NULL,
  `opening_balance` decimal(10,2) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;



DROP TABLE IF EXISTS `cart`;
CREATE TABLE `cart` (
  `cart_id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) DEFAULT NULL,
  `qty` int(11) DEFAULT NULL,
  `rate` double DEFAULT NULL,
  `discount` double DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `cart_type` int(11) DEFAULT NULL COMMENT '1-purchase_cart 2- sales_cart',
  `invoicedate` varchar(255) DEFAULT NULL,
  `invoiceno` varchar(255) DEFAULT NULL,
  `entrydate` varchar(255) DEFAULT NULL,
  `sup-cust_id` int(11) DEFAULT NULL,
  `location` int(11) DEFAULT NULL,
  `to_location` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`cart_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2635 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



DROP TABLE IF EXISTS `despatch`;
CREATE TABLE `despatch` (
  `despatch_id` int(11) NOT NULL AUTO_INCREMENT,
  `do_no` int(50) DEFAULT NULL,
  `challan_no` varchar(11) DEFAULT NULL,
  `vehicle_no` int(50) DEFAULT NULL,
  `quantity` float DEFAULT NULL,
  `ref_no` varchar(150) DEFAULT NULL,
  `rest_amount` decimal(10,2) DEFAULT NULL,
  `shortage` decimal(10,2) DEFAULT NULL,
  `shortage_price` decimal(10,2) DEFAULT NULL,
  `freight` decimal(10,2) DEFAULT NULL,
  `dieselQty` decimal(10,2) DEFAULT NULL,
  `dieselPrice` decimal(10,2) DEFAULT NULL,
  `totaldieselRate` decimal(10,2) DEFAULT NULL,
  `driver_expence` decimal(10,2) DEFAULT NULL,
  `total_deduction` decimal(10,2) DEFAULT NULL,
  `net_amount` decimal(10,2) DEFAULT NULL,
  `deposit_by` varchar(250) DEFAULT NULL,
  `deposited` int(11) DEFAULT 0 COMMENT '1=yes cash deposited 0= No cash not deposited',
  `deposit_date` date DEFAULT NULL,
  `des_date` date DEFAULT NULL,
  `commition` decimal(10,2) DEFAULT NULL,
  `tds` decimal(10,2) DEFAULT NULL,
  `other_deduction` decimal(10,2) DEFAULT NULL,
  `payment_status` int(11) DEFAULT 0,
  `received_date` date DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`despatch_id`)
) ENGINE=InnoDB AUTO_INCREMENT=54077 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;



DROP TABLE IF EXISTS `despatch_fetch_api_data`;
CREATE TABLE `despatch_fetch_api_data` (
  `despatch_id` int(11) NOT NULL AUTO_INCREMENT,
  `PassNo` varchar(250) DEFAULT NULL,
  `VehicleType` varchar(250) DEFAULT NULL,
  `VehicleNo` varchar(250) DEFAULT NULL,
  `SourceUser` varchar(250) DEFAULT NULL,
  `SourceAddress` varchar(250) DEFAULT NULL,
  `MineralName` varchar(250) DEFAULT NULL,
  `MineralForm` varchar(250) DEFAULT NULL,
  `MineralGrade` varchar(250) DEFAULT NULL,
  `MineralQuantity` varchar(250) DEFAULT NULL,
  `DateTimeDispatched` varchar(250) DEFAULT NULL,
  `DestinationUser` varchar(250) DEFAULT NULL,
  `DestinationAddress` varchar(250) DEFAULT NULL,
  `NameOfDriver` varchar(250) DEFAULT NULL,
  `DriverContactNo` varchar(250) DEFAULT NULL,
  `Status` varchar(250) DEFAULT NULL,
  `deposit_by` varchar(250) DEFAULT NULL,
  `deposited` int(11) DEFAULT 0 COMMENT '1=yes cash deposited 0= No cash not deposited',
  `deposit_date` date DEFAULT NULL,
  `des_date` date DEFAULT NULL,
  `commition` decimal(10,2) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`despatch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;



DROP TABLE IF EXISTS `diselentry`;
CREATE TABLE `diselentry` (
  `diselentry_id` int(11) NOT NULL AUTO_INCREMENT,
  `vendor_id` int(11) DEFAULT NULL,
  `vehicle_id` int(11) DEFAULT NULL,
  `diesel_date` date DEFAULT NULL,
  `qty` decimal(10,2) DEFAULT NULL,
  `rate` decimal(10,2) DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`diselentry_id`)
) ENGINE=InnoDB AUTO_INCREMENT=28714 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;



DROP TABLE IF EXISTS `do_registration`;
CREATE TABLE `do_registration` (
  `do_registration_id` int(11) NOT NULL AUTO_INCREMENT,
  `do_no` varchar(250) DEFAULT NULL,
  `route_id` int(11) DEFAULT NULL,
  `diesel_type` varchar(250) DEFAULT NULL,
  `trip_expenses` decimal(10,2) DEFAULT NULL,
  `bonus` decimal(10,2) DEFAULT NULL,
  `party` varchar(250) DEFAULT NULL,
  `from_date` date DEFAULT NULL,
  `to_date` date DEFAULT NULL,
  `rate` decimal(10,2) DEFAULT NULL,
  `max_trip` int(11) DEFAULT NULL,
  `trip_expenses1` decimal(10,2) DEFAULT NULL,
  `trip_expenses2` decimal(10,2) DEFAULT NULL,
  `trip_expenses3` decimal(10,2) DEFAULT NULL,
  `trip_expenses4` decimal(10,2) DEFAULT NULL,
  `trip_expenses5` decimal(10,2) DEFAULT NULL,
  `trip_expenses6` decimal(10,2) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`do_registration_id`)
) ENGINE=InnoDB AUTO_INCREMENT=284 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;



DROP TABLE IF EXISTS `doprice_change`;
CREATE TABLE `doprice_change` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `dono` varchar(250) DEFAULT NULL,
  `trip1` decimal(10,2) DEFAULT NULL,
  `trip2` decimal(10,2) DEFAULT NULL,
  `trip3` decimal(10,2) DEFAULT NULL,
  `trip4` decimal(10,2) DEFAULT NULL,
  `trip5` decimal(10,2) DEFAULT NULL,
  `trip6` decimal(10,2) DEFAULT NULL,
  `from_date` date DEFAULT NULL,
  `to_date` date DEFAULT NULL,
  `rate` decimal(10,2) DEFAULT NULL,
  `created_date` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



DROP TABLE IF EXISTS `driver_assignment`;
CREATE TABLE `driver_assignment` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `vehicle_no` varchar(255) DEFAULT NULL,
  `driver` varchar(255) DEFAULT NULL,
  `from_date` date DEFAULT NULL,
  `opening_hsd` double DEFAULT NULL,
  `opening_km` double DEFAULT NULL,
  `to_date` date DEFAULT NULL,
  `closing_hsd` double DEFAULT NULL,
  `closing_km` double DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2807 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;



DROP TABLE IF EXISTS `financial_year`;
CREATE TABLE `financial_year` (
  `fy_id` int(11) NOT NULL AUTO_INCREMENT,
  `from_date` date NOT NULL,
  `to_date` date NOT NULL,
  `status` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`fy_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



